		if (message.NoRelatedSym      is not null) context.Validators.NoRelatedSym(context, message, message.NoRelatedSym);
		if (message.Subject           is not null) context.Validators.Subject(context, message, message.Subject);
		if (message.EmailThreadID     is not null) context.Validators.EmailThreadID(context, message, message.EmailThreadID);
		if (message.NoRoutingIDs      is not null) context.Validators.NoRoutingIDs(context, message, message.NoRoutingIDs);
		if (message.EncodedSubjectLen is not null) context.Validators.EncodedSubjectLen(context, message, message.EncodedSubjectLen);
		if (message.EncodedSubject    is not null) context.Validators.EncodedSubject(context, message, message.EncodedSubject);
		if (message.NoLegs            is not null) context.Validators.NoLegs(context, message, message.NoLegs);
		if (message.NoUnderlyings     is not null) context.Validators.NoUnderlyings(context, message, message.NoUnderlyings);

		Counted(message, message.NoRelatedSym, message.InstrmtGrp);
		Counted(message, message.NoLegs, message.InstrmtLegGrp);
		Counted(message, message.LinesOfText, message.LinesOfTextGrp);
		Counted(message, message.NoRoutingIDs, message.RoutingGrp);
		Counted(message, message.NoUnderlyings, message.UndInstrmtGrp);

		if (message.InstrmtGrp is not null)
			for (var i = 0; i < message.InstrmtGrp.Count; i++)
				context.Validators.InstrmtGrp(context, message, message.InstrmtGrp[i], i);
		if (message.InstrmtLegGrp is not null)
			for (var i = 0; i < message.InstrmtLegGrp.Count; i++)
				context.Validators.InstrmtLegGrp(context, message, message.InstrmtLegGrp[i], i);
		if (message.LinesOfTextGrp is not null)
			for (var i = 0; i < message.LinesOfTextGrp.Count; i++)
				context.Validators.LinesOfTextGrp(context, message, message.LinesOfTextGrp[i], i);
		if (message.RoutingGrp is not null)
			for (var i = 0; i < message.RoutingGrp.Count; i++)
				context.Validators.RoutingGrp(context, message, message.RoutingGrp[i], i);
		if (message.UndInstrmtGrp is not null)
			for (var i = 0; i < message.UndInstrmtGrp.Count; i++)
				context.Validators.UndInstrmtGrp(context, message, message.UndInstrmtGrp[i], i);

		return message.IsValid;
	}

